#ifndef MS2X_SYNTHETIC_IMAGE_H
#define MS2X_SYNTHETIC_IMAGE_H
#include "ms2x.h"

/* Deterministic non-firmware bytes; hashes independently generated by hashlib.
 * Used with both catalogs to prove only the test catalog accepts this input. */
static void synthetic_image(uint8_t *bytes, const ms2x_profile *p)
{
    for (size_t i=0U; i<p->image_size; ++i)
        bytes[i]=(uint8_t)((i*17U+(size_t)p->hardware*3U+i/251U)&255U);
    bytes[p->version_offset]=5U;
    bytes[p->version_offset+1U]=6U;
    bytes[p->version_offset+2U]=(uint8_t)(p->hardware>>8);
    bytes[p->version_offset+3U]=(uint8_t)p->hardware;
}
#endif
